function getNum(ctx, name, fallback) {
  try { var v = ctx.variables.getVar(name); return Number(v == null || v === "" ? fallback : v); }
  catch (e) { return Number(window[name] == null ? fallback : window[name]); }
}
var p = getNum(this, "pid_p", 1);
var i = getNum(this, "pid_i", 0);
var d = getNum(this, "pid_d", 0);
var step = Math.max(0.001, Number(dt) || 0.1);
var error = Number(target) - Number(current);
window.pid_integral = Number(window.pid_integral || 0) + error * step;
var derivative = (error - Number(window.pid_last_error || 0)) / step;
window.pid_last_error = error;
var output = p * error + i * window.pid_integral + d * derivative;
try {
  this.variables.setVar("pid_error", error);
  this.variables.setVar("pid_integral", window.pid_integral);
  this.variables.setVar("pid_derivative", derivative);
} catch (e) {}
return output;

