var angles = (readMu.angles || []).map(function (a) { return Math.round(Number(a)); });
var current = !isFinite(angles[idx]) ? 0 : (angles[idx] - 2048) * 360 / 4096;
var step = Math.max(0.001, Number(dt) || 0.1);
