function unwrap(x) {
  if (x && typeof x === "object") {
    if (typeof x.itemsArray === "function") { var t = x.itemsArray(); return t.length === 1 ? unwrap(t[0]) : NaN; }
    if (Array.isArray(x)) { return x.length === 1 ? unwrap(x[0]) : NaN; }
  }
  return (x === null || x === undefined || x === "") ? NaN : Number(x);
}
function toNums(v) {
  if (v === null || v === undefined) return [];
  var a;
  if (typeof v === "object") {
    if (typeof v.itemsArray === "function") a = v.itemsArray();
    else if (Array.isArray(v)) a = v;
    else if (typeof v.asArray === "function") a = v.asArray();
    else if (v.contents) a = v.contents;
    else a = [];
  } else {
    var s = String(v).trim();
    if (s === "") return [];
    try { a = JSON.parse(s); } catch (e) { a = s.replace(/[\[\]]/g, "").split(/[,\s]+/); }
    if (!Array.isArray(a)) a = [a];
  }
  return a.map(unwrap);
}
